{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "처방이 의심스러울 때 투약을 멈추고 담당자에게 확인할 수 있는지 평가한다. 평소와 다른 처방 용량을 그대로 투여하지 않고 확인 대상으로 판단한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원 정형외과 병동 근무 중 수술 후 환자의 진통제 처방 용량이 평소의 두 배로 입력된 일이 있었다.",
          "task": "지원자는 수술 전후 환자의 투약·처치를 맡았으며, 해당 처방의 투약을 멈추고 담당의에게 확인했다.",
          "action": "당시 처방을 의심한 구체적인 근거와 확인 전에는 투약하지 않기로 판단한 이유를 설명한다.",
          "result": "담당의 확인으로 입력 오류임을 알게 된 사실이 당시 판단의 근거와 어떤 관계인지 설명한다."
        },
        "expectedEvidence": [
          "투약을 멈추고 담당의에게 확인하기로 판단한 근거",
          "처방 용량을 평소 용량과 비교해 의심한 구체적인 내용",
          "확인 전 처방을 그대로 수행하지 않은 이유"
        ]
      },
      "question": "푸른결종합병원에서 수술 후 환자의 진통제 처방 용량이 평소의 두 배였을 때, 투약을 멈추고 담당의에게 확인하기로 판단한 근거는 무엇이었나요?",
      "answerTip": "본인이 했던 판단을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "평소 용량과 해당 처방의 차이를 구체적으로 짚어 처방을 의심한 근거를 설명한다.",
            "용량 차이를 임의로 해석해 투약하지 않고 담당의 확인 전까지 멈춰야 한다고 판단한 이유를 환자 안전과 연결해 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "평소보다 용량이 많아 투약을 멈추고 확인했다고 답하지만, 당시 비교한 내용의 설명은 제한적이다.",
            "확인이 필요하다는 판단은 타당하지만, 투약을 보류한 이유를 일반적인 안전 원칙 수준으로 설명한다."
          ]
        },
        "poor": {
          "criteria": [
            "입력 오류였다는 결과만 반복하고 당시 투약을 멈춘 판단 근거는 설명하지 못한다.",
            "처방이 의심스러워도 그대로 투여하거나 임의로 용량을 바꿔도 된다는 근거를 제시한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "환자 상태와 관련된 정보를 다음 근무자가 놓치지 않도록 인수인계에 연결할 수 있는지 평가한다. 사고 보고서에서 확인한 교대 시간대의 낙상 양상이 인수인계 항목 선택을 어떻게 바꿨는지에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "낙상 고위험 환자 인수인계 체크리스트 개선 활동에서 사고 보고서를 통해 수술 후 첫 보행 환자의 낙상이 근무 교대 시간대에 몰린다는 점을 확인했다.",
          "task": "지원자는 인수인계 체크리스트에 진통제 투여 시각과 보행 보조 여부를 넣자고 제안했다.",
          "action": "사고 보고서에서 확인한 내용과 두 항목의 선택 근거를 연결해 설명하고, 다음 근무자에게 해당 정보를 전달할 필요가 있다고 판단한 이유를 밝힌다.",
          "result": "두 항목을 전달하면 다음 근무자가 환자 상태와 보행 시 주의할 사항을 파악하는 데 어떤 도움이 된다고 판단했는지 설명한다."
        },
        "expectedEvidence": [
          "진통제 투여 시각과 보행 보조 여부를 인수인계 항목으로 선택한 근거",
          "선택 근거가 된 사고 보고서의 교대 시간대 낙상 양상",
          "두 항목이 다음 근무자의 환자 상태 파악에 필요한 이유"
        ]
      },
      "question": "낙상 고위험 환자 인수인계 체크리스트 개선 활동에서 진통제 투여 시각과 보행 보조 여부를 추가하자고 제안하셨을 때, 두 항목을 인수인계에 넣기로 판단한 근거는 무엇이었나요?",
      "answerTip": "당시 상황을 짧게 짚고 답해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "사고 보고서에서 확인한 교대 시간대의 첫 보행 환자 낙상 양상을 두 항목의 선택 근거와 구체적으로 연결한다.",
            "진통제 투여 시각과 보행 보조 여부가 다음 근무자의 환자 상태 파악과 보행 시 주의사항 판단에 필요한 이유를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "교대 시간대 낙상을 줄이려는 항목 선택이었다고 답하지만, 사고 보고서의 내용과 연결한 설명은 제한적이다.",
            "두 항목을 다음 근무자에게 전달할 필요성은 설명하지만, 환자 상태 파악에 어떤 도움이 되는지는 일반적으로 설명한다."
          ]
        },
        "poor": {
          "criteria": [
            "체크리스트에 추가한 항목이나 낙상 감소 결과만 반복하고 항목을 선택한 근거는 설명하지 못한다.",
            "서식의 편의성 등만을 근거로 들고 환자 상태 정보를 다음 근무자에게 전달할 필요성과 연결하지 못한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P04",
  "interviews": [
    {
      "categoryId": "P04-C1",
      "itemId": "P04-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "주어진 하중이 축 지름 결정에 어떤 영향을 주었는지 확인한다. 하중이 전달되는 경로와 베어링 등 조립 상대 부품을 연결해 치수 선정의 근거를 설명하는지에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "기계요소설계 수업의 감속기 축 설계 계산 과제에서 교재에 주어진 하중 조건을 사용했다.",
          "task": "축 지름과 베어링을 선정하고 손도면과 계산서를 제출하는 개인 과제였다.",
          "action": "축 지름을 정할 때 주어진 하중이 어떤 판단으로 이어졌는지 설명한다. 하중이 전달되는 경로와 베어링 결합 조건 중 실제 선정 근거로 사용한 내용을 연결해 설명한다.",
          "result": "설명한 근거가 제출한 계산서나 손도면의 축 지름과 어떻게 연결되는지 설명한다."
        },
        "expectedEvidence": [
          "주어진 하중을 축 지름에 반영한 판단 근거",
          "판단을 뒷받침하는 하중 경로 또는 베어링 결합 조건",
          "판단 근거와 선정한 축 지름 사이의 연결"
        ]
      },
      "question": "기계요소설계 수업의 감속기 축 설계 계산 과제에서 축 지름을 정하셨을 때, 주어진 하중을 축 지름에 반영한 근거는 무엇이었나요?",
      "answerTip": "직접 판단한 내용을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "과제의 하중 조건이 축 지름 결정에 미친 영향을 구체적으로 설명한다.",
            "하중이 전달되는 경로와 베어링 등 상대 부품의 결합 조건을 축 지름 선정 근거에 일관되게 연결한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "하중에 따라 축 지름을 정한 근거를 제시하지만 실제 과제 조건과의 연결이 일부 불분명하다.",
            "하중 경로나 베어링 결합 조건을 언급하지만 축 지름 결정에 미친 영향은 일반적인 설명에 머문다."
          ]
        },
        "poor": {
          "criteria": [
            "선정한 축 지름이나 계산 결과만 말하고 하중을 반영한 판단 근거를 설명하지 못한다.",
            "제시한 근거가 하중 조건이나 상대 부품과 무관하거나 축 지름 결정과 모순된다."
          ]
        }
      }
    },
    {
      "categoryId": "P04-C1",
      "itemId": "P04-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "양산 도면에서 기능에 필요한 치수만 공차를 좁히는 판단을 확인한다. 모든 치수에 좁은 공차가 지정된 상황에서 기능과 조립 관계에 따라 공차를 구분하는 첫 조치에 초점을 둔다.",
        "questionType": "situational",
        "expectedSTAR": {
          "situation": "입사 후 감속기 부품의 3D 모델을 옮긴 양산 도면에 모든 치수의 공차가 좁게 지정되어 있다.",
          "task": "기능에 필요한 치수를 구분해 과도하게 지정된 공차를 바로잡을 첫 조치를 정한다.",
          "action": "상대 부품과 맞물리는 치수나 기능을 좌우하는 치수를 먼저 확인하는 등 공차를 구분할 구체적인 첫 조치를 제시한다. 주어진 정보가 부족하면 확인할 기능과 조립 관계를 짚는다.",
          "result": "제시한 조치로 좁은 공차가 필요한 치수와 완화할 수 있는 치수를 구분할 수 있을 것으로 예상한다."
        },
        "expectedEvidence": [
          "양산 도면의 공차를 바로잡을 구체적인 첫 조치",
          "그 조치에서 확인하거나 구분할 기능 치수와 조립 관계"
        ]
      },
      "question": "입사 후 감속기 부품의 3D 모델을 옮긴 양산 도면에 모든 치수의 공차가 좁게 잡혀 있다면, 가장 먼저 도면을 바로잡을 조치는 무엇인가요?",
      "answerTip": "생각을 정리한 뒤 간결하게 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "기능이나 상대 부품과의 조립 관계를 확인해 공차를 구분하는 구체적인 첫 조치를 제시한다.",
            "제시한 조치가 기능에 필요한 치수의 좁은 공차는 유지하고 불필요하게 좁은 공차는 구분하는 방향과 맞는다."
          ]
        },
        "acceptable": {
          "criteria": [
            "공차를 검토하거나 필요한 정보를 확인하는 타당한 첫 조치를 제시하지만 확인 대상이 포괄적이다.",
            "기능에 따라 공차를 달리해야 한다고 답하지만 첫 조치에서 치수를 구분할 대상이 일부 불분명하다."
          ]
        },
        "poor": {
          "criteria": [
            "공차의 정의나 설계 도구 사용법만 설명하고 도면을 바로잡을 첫 조치를 제시하지 못한다.",
            "기능과 조립 관계를 고려하지 않고 모든 공차를 일괄적으로 유지하거나 완화하겠다고 답한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P05",
  "interviews": [
    {
      "categoryId": "P05-C2",
      "itemId": "P05-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "분석 결론을 캠페인 실행 계획의 타깃과 접촉 순서로 옮기는 판단을 확인한다. 발주 품목과 시기에서 파악한 교체 주기가 연락 우선순위를 정하는 근거로 연결됐는지에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "오름퍼니처에서 6개월 이상 발주가 없는 거래처를 대상으로 재접촉 캠페인을 진행했다.",
          "task": "거래처의 마지막 발주 품목과 시기를 엑셀로 정리하고 의자·파티션 교체 주기가 돌아온 곳부터 연락 순서를 정했다.",
          "action": "발주 품목과 시기로 파악한 교체 수요가 거래처별 연락 우선순위를 정하는 데 어떤 근거가 됐는지 설명한다.",
          "result": "분석 결론이 실제 연락 순서에 반영된 내용을 설명하고, 14곳의 재주문 결과와 구분해 판단 당시의 근거를 제시한다."
        },
        "expectedEvidence": [
          "발주 품목과 시기를 연락 우선순위에 반영한 판단 근거",
          "교체 주기가 돌아왔다고 판단하는 데 사용한 거래처별 발주 정보",
          "분석 결론과 실제 연락 순서의 연결"
        ]
      },
      "question": "오름퍼니처의 휴면 거래처 재접촉 캠페인에서 연락 순서를 정하셨을 때, 발주 품목과 시기를 연락 우선순위에 반영한 근거는 무엇이었나요?",
      "answerTip": "본인이 한 일을 중심으로 간결하게 말해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "마지막 발주 품목과 시기를 교체 수요의 단서로 해석해 연락 우선순위를 정한 근거를 구체적으로 설명한다.",
            "단순히 오래 발주하지 않은 순서가 아니라 분석에서 파악한 교체 주기가 실제 접촉 대상과 순서에 연결됐음을 명확히 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "발주 품목이나 시기를 보고 교체 가능성이 높은 거래처부터 연락했다고 설명하지만 판단 근거가 포괄적이다.",
            "분석 결과와 연락 우선순위의 연결은 제시하지만 거래처별 정보를 우선순위에 반영한 설명이 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "연락 우선순위를 정한 근거 대신 재주문 건수나 매출 성과만 말한다.",
            "발주 정보와 연락 순서의 연결을 설명하지 못하고 거래처에 자주 연락해야 한다는 일반론에 머문다."
          ]
        }
      }
    },
    {
      "categoryId": "P05-C2",
